public class T {
  static final String CC="61";
  static String norm(String telephone){
    if(telephone==null)return null;
    boolean hasCC=telephone.trim().startsWith("+");
    String digits=telephone.replaceAll("\\D","");
    String r;
    if(hasCC){r=digits;}else{ if(digits.startsWith("0"))digits=digits.substring(1); r=CC+digits;}
    if(!r.matches("\\d{8,15}"))throw new RuntimeException("BAD "+telephone+" -> "+r+" len="+r.length());
    return "+"+r;
  }
  public static void main(String[] a){
    System.out.println(norm("0400000004"));
    System.out.println(norm("6085551023"));
  }
}
